import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

(()=>{'use strict';
const $=id=>document.getElementById(id);
const PARTS=[{id:'frame',name:'Motorcycle frame',icon:'▱',slot:'FRAME'},{id:'wheel1',name:'Front tire',icon:'◉',slot:'FRONT TIRE'},{id:'wheel2',name:'Rear tire',icon:'◉',slot:'REAR TIRE'},{id:'bars',name:'Handlebars',icon:'⌁',slot:'HANDLEBARS'},{id:'engine',name:'Engine block',icon:'⚙',slot:'ENGINE'},{id:'tank',name:'Oil tank',icon:'◒',slot:'OIL TANK'}];
const inventory={scrap:0,food:1,water:1,med:1,ammo:6,armor:0};
let installed={},state='assembly',health=100,fuel=100,distance=0,bike=0,frameType='standard',ammo=6,kills=0,elapsed=0,shootCooldown=0,meleeCooldown=0,muted=false,notice='',toastTimer=0,lootNearby=false,nextEnemyAt=7,nextLootAt=10,lastUI=0;
const keys={};
const viewport=$('viewport'),canvas=$('gameCanvas');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9a927a);scene.fog=new THREE.Fog(0x9a927a,45,230);
const camera=new THREE.PerspectiveCamera(62,1,.1,600);camera.position.set(0,4.2,8.5);
scene.add(new THREE.HemisphereLight(0xd8d2ba,0x48463a,2.1));const sun=new THREE.DirectionalLight(0xffe1ad,3.2);sun.position.set(-35,55,25);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
const mat=(color,roughness=.85)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={soil:mat(0x77705a),road:mat(0x403f3b),stripe:mat(0xc8b57d),dark:mat(0x171b1b),rubber:mat(0x191c1b),metal:mat(0x99978a),rust:mat(0xb85d3e),frame:mat(0x383c37),leather:mat(0x30332e),skin:mat(0xb77b5d),helmet:mat(0x343b35),green:mat(0x66684e),wood:mat(0x665744),loot:mat(0xd6b85f),white:mat(0xd7d1bd)};
function mesh(geo,material,parent=scene){const o=new THREE.Mesh(geo,material);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function box(parent,material,x,y,z,sx,sy,sz){const o=mesh(new THREE.BoxGeometry(sx,sy,sz),material,parent);o.position.set(x,y,z);return o}
function cylinder(parent,material,x,y,z,r1,r2,len,axis='y',segments=12){const o=mesh(new THREE.CylinderGeometry(r1,r2,len,segments),material,parent);o.position.set(x,y,z);if(axis==='x')o.rotation.z=Math.PI/2;if(axis==='z')o.rotation.x=Math.PI/2;return o}
function sphere(parent,material,x,y,z,sx,sy,sz){const o=mesh(new THREE.SphereGeometry(1,12,8),material,parent);o.position.set(x,y,z);o.scale.set(sx,sy,sz);return o}

// Endless low-poly road and a broad, steerable wasteland floor.
const ground=mesh(new THREE.PlaneGeometry(1200,1200),mats.soil);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;
const roadSegments=[],roadLength=90;
for(let i=0;i<9;i++){const g=new THREE.Group();scene.add(g);box(g,mats.road,0,-.015,-roadLength/2,13,.08,roadLength);for(let z=-roadLength+5;z<0;z+=12)box(g,mats.stripe,0,.04,z,.18,.025,5);roadSegments.push(g);g.position.z=-i*roadLength}
const props=[];
function makeTree(x,z,seed){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);cylinder(g,mats.wood,0,1.1,0,.22,.34,2.2);for(let j=0;j<3;j++){const crown=mesh(new THREE.ConeGeometry(1.25-j*.18,2.2,5),mat(seed%2?0x686b50:0x777054),g);crown.position.set((j-1)*.15,2.3+j*.72,0)}props.push({group:g,kind:'tree'})}
for(let i=0;i<56;i++){let z=-20-i*13;makeTree((i%2?1:-1)*(12+(i*17)%30),z,i)}
function makeRuin(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,mats.wood,0,1.2,0,7,2.4,4);box(g,mats.soil,0,2.45,0,7.8,.3,4.7);box(g,mats.dark,-1.7,.8,-2.02,1.2,1.6,.1);box(g,mats.dark,1.7,.8,-2.02,1.1,1.1,.1);box(g,mats.rust,0,2.95,-2.1,2,.55,.12);props.push({group:g,kind:'ruin'})}
makeRuin(25,-105);makeRuin(-30,-260);makeRuin(28,-430);

const bikeRoot=new THREE.Group();scene.add(bikeRoot);const bikeModel=new THREE.Group();bikeRoot.add(bikeModel);
const rearWheel=new THREE.Group();rearWheel.position.set(0,.48,.9);bikeModel.add(rearWheel);const frontWheel=new THREE.Group();frontWheel.position.set(0,.48,-1.12);bikeModel.add(frontWheel);
for(const wheel of [rearWheel,frontWheel]){cylinder(wheel,mats.rubber,0,0,0,.47,.47,.23,'x',20);cylinder(wheel,mats.metal,0,0,0,.24,.24,.25,'x',12);for(let i=0;i<8;i++){const spoke=box(wheel,mats.metal,0,0,0,.035,.38,.025);spoke.rotation.x=i*Math.PI/4}}
cylinder(bikeModel,mats.rust,0,.67,.1,.1,.1,1.75,'x');cylinder(bikeModel,mats.rust,0,.68,.1,.1,.1,1.45,'z');
box(bikeModel,mats.frame,0,.83,.05,.58,.48,.55);box(bikeModel,mats.metal,0,.76,.13,.64,.18,.5);const tank=sphere(bikeModel,mats.rust,0,1.13,-.25,.42,.3,.62);tank.rotation.x=-.13;
box(bikeModel,mats.leather,0,1.18,.38,.58,.16,.53);cylinder(bikeModel,mats.metal,0,.67,.5,.055,.055,.8,'x');
const fork=cylinder(bikeModel,mats.metal,0,1.03,-.94,.07,.07,.96,'z');fork.rotation.x=-.12;cylinder(bikeModel,mats.metal,0,1.35,-1.2,.045,.045,.82,'x');cylinder(bikeModel,mats.dark,0,1.32,-1.18,.07,.07,.5,'z');sphere(bikeModel,mats.loot,0,1.31,-1.51,.18,.14,.08);
const rider=new THREE.Group();bikeModel.add(rider);rider.position.set(0,1.34,.12);const torso=box(rider,mats.leather,0,.28,.05,.62,.75,.38);torso.rotation.x=-.24;
sphere(rider,mats.skin,0,.9,-.08,.24,.27,.24);sphere(rider,mats.helmet,0,1.03,-.08,.3,.28,.3);box(rider,mats.white,0,.94,-.32,.3,.09,.04);
for(const s of [-1,1]){const leg=box(rider,mats.leather,s*.23,-.17,.35,.2,.56,.22);leg.rotation.x=-.48;const boot=box(rider,mats.dark,s*.24,-.35,-.01,.22,.16,.42);boot.rotation.x=-.2;const arm=box(rider,mats.leather,s*.35,.43,-.25,.16,.54,.16);arm.rotation.x=-.72;arm.rotation.z=s*.16;sphere(rider,mats.dark,s*.36,.19,-.48,.13,.11,.14)}

const enemies=[],loot=[];
function makeEnemy(z,x){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);const skin=mat(0x85866a),cloth=mat(Math.random()<.25?0x76513d:0x626353);box(g,cloth,0,1.05,0,.68,.85,.38);sphere(g,skin,0,1.72,-.02,.29,.31,.27);for(const s of [-1,1]){box(g,cloth,s*.47,1.12,-.08,.2,.62,.2).rotation.z=s*.32;box(g,mat(0x34362e),s*.2,.35,.03,.22,.62,.24)}sphere(g,mat(0xc4563b),-.1,1.76,-.265,.045,.035,.025);sphere(g,mat(0xc4563b),.1,1.76,-.265,.045,.035,.025);g.userData={hp:Math.random()<.2?3:2,elite:false,attack:0,phase:Math.random()*5};enemies.push(g);return g}
function makeLoot(z,x){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);box(g,mats.wood,0,.38,0,.9,.72,.72);box(g,mats.loot,0,.78,0,.68,.08,.54);const beacon=mesh(new THREE.OctahedronGeometry(.2),mats.loot,g);beacon.position.y=1.15;loot.push(g);return g}
function log(text){const el=document.createElement('div');el.className='log-line';el.textContent=text;const l=$('log');l.prepend(el);while(l.children.length>3)l.removeChild(l.lastChild)}
function toast(text){notice=text;toastTimer=2.4;log(text)}
function showOverlay(html){$('cardContent').innerHTML=html;$('overlay').hidden=false}
function hideOverlay(){$('overlay').hidden=true}
function assemblyCard(){const list=PARTS.map(p=>{const ok=installed[p.id];return `<button class="part-slot ${ok?'installed':'missing'}" data-part="${p.id}"><span class="slot-icon">${p.icon}</span><span class="slot-label">${p.slot}</span><span class="slot-state">${ok?'✓ FITTED':'＋ FIT'}</span></button>`}).join('');showOverlay(`<div class="card-kicker">STOP 00 &nbsp; / &nbsp; THE GARAGE</div><h2>BUILD YOUR<br>WAY OUT.</h2><p>The coast is five hundred miles west. The dead own the roads. Fit every part to get your engine turning — then keep it turning.</p><div class="assembly-grid">${list}</div><div class="assembly-note">FRAME: <b>${frameType.toUpperCase()}</b> &nbsp; · &nbsp; FITTED ${Object.keys(installed).length}/6</div><div class="assembly-actions"><button class="primary" id="rideBtn" ${Object.keys(installed).length<6?'disabled style="opacity:.45;cursor:not-allowed"':''}>${Object.keys(installed).length<6?'FIT ALL PARTS TO RIDE':'START THE ENGINE →'}</button><small>Tap a slot to fit its part</small></div>`);document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{const id=b.dataset.part;if(installed[id]){toast('That part is already fitted.');return}installed[id]=true;b.classList.remove('missing');b.classList.add('installed');b.querySelector('.slot-state').textContent='✓ FITTED';document.querySelector('.assembly-note').innerHTML=`FRAME: <b>${frameType.toUpperCase()}</b> &nbsp; · &nbsp; FITTED ${Object.keys(installed).length}/6`;const btn=$('rideBtn');if(Object.keys(installed).length===6){btn.disabled=false;btn.style.opacity='1';btn.style.cursor='pointer';btn.textContent='START THE ENGINE →';toast('All systems fit. She runs.')}updateUI()});$('rideBtn').onclick=()=>{if(Object.keys(installed).length===6)startRide()}}
function startRide(){state='ride';bike=100;hideOverlay();$('sceneTitle').textContent='THE ROAD DOESN’T END';$('objective').innerHTML='<span>YOUR OBJECTIVE</span><b>Ride west. Search every stop. Stay alive.</b>';log('Engine catches. The road is yours.');log('W throttle · A/D steer · E search · Space wrench · click fire');updateUI()}
function gameEnd(win=false){state='end';showOverlay(`<div class="card-kicker">${win?'MILE 500 &nbsp; / &nbsp; THE COAST':'YOUR RIDE ENDS HERE'}</div><h2>${win?'YOU MADE IT.':'THE ROAD TAKES ALL.'}</h2><p>${win?`You crossed the dead country with ${health} health, ${kills} threats cleared, and a bike held together by stubbornness.`:`You made it ${Math.floor(distance)} miles. ${kills} threats won't be following anyone now.`} The coast is still out there.</p><button class="primary" id="restartBtn">RIDE AGAIN →</button>`);$('restartBtn').onclick=()=>location.reload()}
function updateUI(){const hp=Math.max(0,Math.round(health));$('healthNum').textContent=hp;$('healthBar').style.width=hp+'%';$('fuelNum').textContent=Math.round(fuel)+'%';$('fuelBar').style.width=Math.max(0,fuel)+'%';$('bikeNum').textContent=bike?Math.round(bike)+'%':'—';$('bikeBar').style.width=bike+'%';$('distanceLabel').textContent=String(Math.floor(distance)).padStart(3,'0');$('milePercent').textContent=Math.floor(distance/5)+'%';$('ammoCount').textContent=ammo;$('scrapCount').textContent=inventory.scrap;$('armorValue').textContent=inventory.armor+'%';$('armorDesc').textContent=inventory.armor?`Impact resistance · ${inventory.armor}% protection`:'No armor fitted';$('armorName').textContent=inventory.armor>=30?'Reinforced leathers':'Road leathers';$('armorLevel').textContent=inventory.armor>=45?'III':inventory.armor>=20?'II':'I';const items=[['⚙','SCR',inventory.scrap,'good'],['🥫','FOOD',inventory.food,''],['◉','WATER',inventory.water,''],['✚','MED',inventory.med,'hot'],['▰','AMMO',ammo,''],['⛽','FUEL',Math.floor(fuel),'good'],['⛨','ARM',inventory.armor?1:0,'good'],['＋','—',0,'empty']];$('inventoryGrid').innerHTML=items.map(([ico,label,n,c])=>`<div class="item ${c}"><span class="item-label">${label}</span>${ico}<span class="count">${n}</span></div>`).join('');$('packCount').textContent=`${Math.min(12,6+inventory.scrap)} / 12`;$('loadCount').textContent=inventory.scrap>8?'HEAVY':inventory.scrap>4?'PACKED':'LIGHT';$('killsCount').textContent=`${kills} THREATS CLEARED`;const region=distance<100?'THE OUTSKIRTS':distance<250?'DEADWOOD COUNTY':distance<400?'THE RUST BELT':'PACIFIC COAST';$('regionLabel').textContent=region;$('dayLabel').textContent=`DAY ${String(1+Math.floor(distance/110)).padStart(2,'0')}`;const idx=distance<100?0:distance<250?1:distance<400?2:3;document.querySelectorAll('.milestone').forEach((m,i)=>m.classList.toggle('active',i===idx));document.querySelectorAll('.milestone')[idx].prepend($('milePercent'))}

function fire(){if(state!=='ride'||ammo<=0||shootCooldown>0)return;ammo--;shootCooldown=.38;$('gunWeapon').classList.add('selected');$('meleeWeapon').classList.remove('selected');const target=enemies.filter(e=>e.position.z<2&&e.position.z>-42).sort((a,b)=>Math.abs(a.position.x-bikeRoot.position.x)-Math.abs(b.position.x-bikeRoot.position.x))[0];if(target){target.userData.hp--;target.position.x+=(target.position.x-bikeRoot.position.x<0?-1:1)*1.2;if(target.userData.hp<=0)killEnemy(target)}updateUI()}
function killEnemy(e){scene.remove(e);const i=enemies.indexOf(e);if(i>=0)enemies.splice(i,1);kills++;if(Math.random()<.7)inventory.scrap++;toast('Target dropped. Road stays clear—for now.');updateUI()}
function swing(){if(state!=='ride'||meleeCooldown>0)return;meleeCooldown=.65;$('meleeWeapon').classList.add('selected');$('gunWeapon').classList.remove('selected');const target=enemies.find(e=>e.position.z<3&&e.position.z>-4&&Math.abs(e.position.x-bikeRoot.position.x)<2.6);if(target){target.userData.hp--;target.position.z+=2;if(target.userData.hp<=0)killEnemy(target);else toast('Wrench connects. Keep moving.')}else toast('Wrench swing. Keep them close.')}
function scavenge(){if(state!=='ride')return;if(!lootNearby){toast('No safehouse close enough. Search the roadside stops ahead.');return}const target=loot[0];if(target){scene.remove(target);loot.shift()}lootNearby=false;const roll=Math.random();if(roll<.2){inventory.food++;toast('Found canned food. +1 ration.')}else if(roll<.38){inventory.water++;toast('Found clean water. +1 bottle.')}else if(roll<.53){inventory.med++;toast('First-aid kit recovered.')}else if(roll<.7){const n=2+Math.floor(Math.random()*4);inventory.scrap+=n;toast(`Useful parts in the wreck. +${n} scrap.`)}else if(roll<.83){ammo+=4;toast('Ammunition in the glovebox. +4 rounds.')}else if(roll<.94){fuel=Math.min(100,fuel+20);toast('Salvaged fuel. +20%.')}else{inventory.armor=Math.min(60,inventory.armor+15);toast('Found a reinforced riding vest. Armor +15%.')}if(Math.random()<.3&&bike<90){bike=Math.min(100,bike+12);toast('A box of bolts. Bike condition +12%.')}updateUI()}
function consume(item){if(state!=='ride')return;if(item==='med'&&inventory.med){inventory.med--;health=Math.min(100,health+38);toast('First aid applied. +38 health.')}else if(item==='food'&&inventory.food){inventory.food--;health=Math.min(100,health+16);toast('Ate a ration. +16 health.')}else if(item==='water'&&inventory.water){inventory.water--;health=Math.min(100,health+10);toast('Water break. +10 health.')}else toast(`No ${item} left in your pack.`);updateUI()}

function update(dt){elapsed+=dt;shootCooldown=Math.max(0,shootCooldown-dt);meleeCooldown=Math.max(0,meleeCooldown-dt);toastTimer=Math.max(0,toastTimer-dt);const riding=state==='ride',throttle=(keys.w||keys.arrowup?1:keys.s||keys.arrowdown?-.3:.72),steer=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),roadSpeed=riding?Math.max(3,throttle>0?13*throttle:4):0;
if(riding){bikeRoot.position.x=THREE.MathUtils.clamp(bikeRoot.position.x+steer*dt*7,-10,10);bikeRoot.rotation.z=THREE.MathUtils.damp(bikeRoot.rotation.z,-steer*.16,5,dt);bikeModel.rotation.x=Math.sin(elapsed*13)*.012*(roadSpeed/13);rearWheel.rotation.x-=roadSpeed*dt*1.6;frontWheel.rotation.x-=roadSpeed*dt*1.6;distance+=roadSpeed*dt*.105;fuel=Math.max(0,fuel-roadSpeed*dt*.014);bike=Math.max(0,bike-roadSpeed*dt*.00065);if(distance>=500){distance=500;updateUI();gameEnd(true);return}if(distance>=nextEnemyAt&&enemies.length<6){makeEnemy(-70-Math.random()*35,(Math.random()-.5)*12);nextEnemyAt=distance+8+Math.random()*10}if(distance>=nextLootAt){makeLoot(-85-Math.random()*20,(Math.random()<.5?-1:1)*(9+Math.random()*9));nextLootAt=distance+18+Math.random()*10}}
const scroll=roadSpeed*dt;for(const g of roadSegments){g.position.z+=scroll;if(g.position.z>roadLength)g.position.z-=roadSegments.length*roadLength}for(const p of props){p.group.position.z+=scroll;if(p.group.position.z>32){p.group.position.z-=760;p.group.position.x=(p.group.position.x<0?-1:1)*(13+Math.random()*31)}}
lootNearby=false;let closeLoot=null;for(const l of [...loot]){l.position.z+=scroll;l.rotation.y+=dt*.6;l.children[l.children.length-1].position.y=1.15+Math.sin(elapsed*3)*.1;if(l.position.z>15){scene.remove(l);loot.splice(loot.indexOf(l),1);continue}if(Math.abs(l.position.z)<7&&Math.abs(l.position.x-bikeRoot.position.x)<15){lootNearby=true;closeLoot=l}}
for(const e of [...enemies]){e.position.z+=scroll+dt*(2+distance*.002);e.position.x+=Math.sin(elapsed*1.4+e.userData.phase)*dt*.35;e.rotation.y=Math.sin(elapsed*2+e.userData.phase)*.1;if(e.position.z>14){scene.remove(e);enemies.splice(enemies.indexOf(e),1);continue}if(Math.abs(e.position.z)<2.5&&Math.abs(e.position.x-bikeRoot.position.x)<1.9){e.userData.attack-=dt;if(e.userData.attack<=0){e.userData.attack=1.35;health=Math.max(0,health-(e.userData.hp>=3?10:6)*(1-inventory.armor/130));bike=Math.max(0,bike-1);toast('The dead grab at your jacket.');updateUI();if(health<=0){gameEnd();return}}}}
if(lootNearby&&closeLoot)$('objective').innerHTML='<span>NEARBY STOP · PRESS E</span><b>Search the roadside stash.</b>';else if(riding&&$('objective').textContent.includes('NEARBY'))$('objective').innerHTML='<span>YOUR OBJECTIVE</span><b>Ride west. Search every stop. Stay alive.</b>';
